const text = $('Siapkan Pesan').first().json.text;

const sistem = `Kamu mengklasifikasi catatan keuangan pribadi berbahasa Indonesia.
Balas HANYA JSON: {"kategori": "...", "keterangan": "..."}
kategori harus salah satu: Makanan, Transport, Belanja, Tagihan, Hiburan, Lainnya, Pemasukan.
keterangan: 2-4 kata, tanpa angka nominal.

Panduan:
- Makanan: makan, minum, kopi, jajan, bahan makanan
- Transport: ojol, bensin, parkir, tol, tiket KRL/bus
- Belanja: barang (baju, sepatu, alat), belanja online
- Tagihan: listrik, air, wifi, paket data, kuota, pulsa, cicilan, langganan
- Hiburan: nonton, game, streaming, rekreasi
- Pemasukan: uang masuk, bukan pengeluaran
- Lainnya: hanya jika benar-benar tidak ada yang cocok

Contoh:
"beli paket data 50rb" -> {"kategori":"Tagihan","keterangan":"paket data"}
"isi pulsa 20rb" -> {"kategori":"Tagihan","keterangan":"pulsa"}
"gojek ke kantor 18rb" -> {"kategori":"Transport","keterangan":"gojek"}
"beli sepatu 450rb" -> {"kategori":"Belanja","keterangan":"sepatu"}
"makan siang 25rb" -> {"kategori":"Makanan","keterangan":"makan siang"}`;

return [{
  json: {
    text,
    body: {
      model: "qwen2.5:3b",
      stream: false,
      format: "json",
      options: { temperature: 0 },
      messages: [
        { role: "system", content: sistem },
        { role: "user", content: "Pesan: " + text }
      ]
    }
  }
}];

const teks = $('Siapkan Pesan').first().json.text;
const raw = $input.first().json.message?.content ?? '';

const KATEGORI = ['Makanan', 'Transport', 'Belanja', 'Tagihan', 'Hiburan', 'Lainnya', 'Pemasukan'];

function gagal(alasan) {
  return [{ json: { valid: false, alasan, teks, balasan: 'Tidak paham, coba tulis ulang.' } }];
}

// Nominal diproses dengan aturan, bukan AI
function parseJumlah(s) {
  const kali = { rb: 1e3, ribu: 1e3, k: 1e3, jt: 1e6, juta: 1e6 };
  const re = /(\d+(?:[.,]\d+)*)\s*(rb|ribu|k|jt|juta)?\b/gi;
  const polos = [];
  let m;
  while ((m = re.exec(s)) !== null) {
    const unit = m[2] ? m[2].toLowerCase() : null;
    if (unit) {
      // "1,5jt" -> 1.5 x 1.000.000
      return Math.round(parseFloat(m[1].replace(',', '.')) * kali[unit]);
    }
    // tanpa satuan: "25.000" atau "25000"
    polos.push(parseInt(m[1].replace(/[.,]/g, ''), 10));
  }
  return polos.length ? Math.max(...polos) : null;
}

const ATURAN = [
  { kategori: 'Tagihan',   kata: ['paket data', 'kuota', 'pulsa', 'token listrik', 'listrik', 'wifi', 'indihome', 'pdam', 'bpjs', 'cicilan'] },
  { kategori: 'Transport', kata: ['gojek', 'grab', 'ojol', 'bensin', 'pertamax', 'parkir', 'tol', 'krl', 'mrt', 'transjakarta'] },
  { kategori: 'Belanja',   kata: ['indomaret', 'alfamart', 'shopee', 'tokopedia', 'lazada'] },
  { kategori: 'Hiburan',   kata: ['netflix', 'spotify', 'bioskop', 'nonton', 'youtube premium'] },
];
const dariAturan = t => {
  const x = t.toLowerCase();
  const a = ATURAN.find(r => r.kata.some(k => x.includes(k)));
  return a ? a.kategori : null;
};
const hasilAturan = dariAturan(teks);

let data = {};
try {
  data = JSON.parse(raw);
} catch (e) {
  if (!hasilAturan) return gagal('Output AI bukan JSON valid');
}

const kategori = hasilAturan ?? data.kategori;
const keterangan = String(data.keterangan ?? '').trim()
  || (hasilAturan ? teks.replace(/\d[\d.,]*\s*(rb|ribu|k|jt|juta)?/gi, '').trim() : '');
const jumlah = parseJumlah(teks);

if (!KATEGORI.includes(kategori)) return gagal('Kategori tidak dikenal: ' + kategori);
if (!keterangan) return gagal('Keterangan kosong');
if (!jumlah || jumlah <= 0) return gagal('Nominal tidak ditemukan');

const tipe = kategori === 'Pemasukan' ? 'Pemasukan' : 'Pengeluaran';

return [{
  json: {
    valid: true,
    tanggal: $now.toFormat('yyyy-MM-dd'),
    jumlah,
    kategori,
    keterangan,
    tipe,
    teks,
    update_id: $('Siapkan Pesan').first().json.update_id,
    status: 'Aktif',
    balasan: `Tercatat: ${kategori} Rp${jumlah.toLocaleString('id-ID')} (${keterangan})`
  }
}];

const store = $getWorkflowStaticData('global');
// Offset awal 0 = baca dari pesan pertama yang belum diambil
return [{ json: { offset: store.offset ?? 0 } }];

const CHAT_ID_SAYA = Number('<YOUR_CHAT_ID>');
const store = $getWorkflowStaticData('global');

const hasil = $input.first().json.result ?? [];
if (hasil.length === 0) return [];            // tidak ada pesan baru, alur berhenti

const update = hasil[0];
store.offset = update.update_id + 1;          // tandai pesan ini sudah dibaca

const msg = update.message;
if (!msg || !msg.text) return [];             // bukan pesan teks
if (msg.chat.id !== CHAT_ID_SAYA) return [];  // bukan dari kamu: diabaikan

const teks = msg.text.trim();
const dasar = { text: teks, chat_id: msg.chat.id, update_id: update.update_id };

if (teks.startsWith('/')) {
  const [kepala, ...sisa] = teks.split(/\s+/);
  const perintah = kepala.slice(1).split('@')[0].toLowerCase(); // buang /, buang @namabot
  return [{ json: { ...dasar, jenis: 'perintah', perintah, argumen: sisa.join(' ') } }];
}

return [{ json: { ...dasar, jenis: 'transaksi' } }];

return [{
  json: {
    chat_id: $('Siapkan Pesan').first().json.chat_id,
    balasan:
`Perintah yang tersedia:
/bantuan - daftar perintah
/saldo - saldo periode ini
/anggaran - sisa anggaran per kategori
/batal - batalkan transaksi terakhir

Contoh mencatat transaksi:
makan siang 25rb
gojek 18.000
dapat uang kiriman 200rb`
  }
}];

const mentah = $input.first().json.Nilai ?? '';
const saldo = parseInt(String(mentah).replace(/[^0-9-]/g, ''), 10);
const chat_id = $('Siapkan Pesan').first().json.chat_id;

if (Number.isNaN(saldo)) {
  return [{ json: { chat_id, balasan: 'Saldo belum bisa dibaca dari tab Pengaturan.' } }];
}

const tanda = saldo < 0 ? '-' : '';
return [{
  json: {
    chat_id,
    balasan: `Saldo periode ini: ${tanda}Rp${Math.abs(saldo).toLocaleString('id-ID')}`
  }
}];

return [{
  json: {
    chat_id: $('Siapkan Pesan').first().json.chat_id,
    balasan: 'Perintah tidak dikenal. Ketik /bantuan untuk melihat daftar perintah.'
  }
}];

const baris = $input.all().map(i => i.json).filter(j => j.row_number);
const chat_id = $('Siapkan Pesan').first().json.chat_id;

if (baris.length === 0) {
  return [{ json: { ada: false, chat_id, balasan: 'Tidak ada transaksi aktif untuk dibatalkan.' } }];
}

const terakhir = baris.reduce((a, b) => (b.row_number > a.row_number ? b : a));
const jumlah = parseInt(String(terakhir.Jumlah).replace(/[^0-9-]/g, ''), 10);

return [{
  json: {
    ada: true,
    chat_id,
    row_number: terakhir.row_number,
    balasan: `Dibatalkan: ${terakhir.Kategori} Rp${jumlah.toLocaleString('id-ID')} (${terakhir.Keterangan})`
  }
}];

const dasar = $('Validasi').first().json;
const chat_id = $('Siapkan Pesan').first().json.chat_id;
const baris = $input.first().json;
let balasan = dasar.balasan;

const angka = v => parseInt(String(v ?? '').replace(/[^0-9-]/g, ''), 10);
const rp = n => 'Rp' + Math.abs(n).toLocaleString('id-ID');

if (dasar.tipe === 'Pengeluaran' && baris['Batas Bulanan']) {
  const batas = angka(baris['Batas Bulanan']);
  const terpakai = angka(baris['Terpakai']);

  if (batas > 0 && !Number.isNaN(terpakai)) {
    const persen = Math.round((terpakai / batas) * 100);
    if (terpakai >= batas) {
      balasan += `\nAnggaran ${dasar.kategori} terlampaui ${rp(terpakai - batas)}.`;
    } else if (persen >= 80) {
      balasan += `\nPerhatian: anggaran ${dasar.kategori} terpakai ${persen}% (sisa ${rp(batas - terpakai)}).`;
    }
  }
}

return [{ json: { chat_id, balasan } }];

const baris = $input.all().map(i => i.json).filter(j => j.Kategori);
const chat_id = $('Siapkan Pesan').first().json.chat_id;

const angka = v => parseInt(String(v ?? '').replace(/[^0-9-]/g, ''), 10);
const rp = n => 'Rp' + Math.abs(n).toLocaleString('id-ID');

if (baris.length === 0) {
  return [{ json: { chat_id, balasan: 'Belum ada anggaran di tab Anggaran.' } }];
}

const garis = baris
  .map(b => ({ kategori: b.Kategori, batas: angka(b['Batas Bulanan']), terpakai: angka(b['Terpakai']) }))
  .filter(b => b.batas > 0 && !Number.isNaN(b.terpakai))
  .map(b => {
    const persen = Math.round((b.terpakai / b.batas) * 100);
    if (b.terpakai >= b.batas) {
      return `${b.kategori}: terlampaui ${rp(b.terpakai - b.batas)} (${persen}%)`;
    }
    const peringatan = persen >= 80 ? ' (!)' : '';
    return `${b.kategori}: sisa ${rp(b.batas - b.terpakai)} (terpakai ${persen}%)${peringatan}`;
  });

return [{
  json: {
    chat_id,
    balasan: 'Anggaran periode ini:\n' + garis.join('\n')
  }
}];

const BULAN = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const PENDEK = ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];
const TGL_MULAI = 2;

let info;
try { info = $('Mode Lalu').first().json; } catch (e) { info = $('Mode Berjalan').first().json; }

const angka = v => { const n = parseInt(String(v ?? '').replace(/[^0-9-]/g, ''), 10); return Number.isNaN(n) ? 0 : n; };
const rp = n => 'Rp' + Math.abs(n).toLocaleString('id-ID');

function keIso(v) {
  const s = String(v ?? '').trim();
  if (typeof v === 'number' || /^\d{5}$/.test(s)) {
    return new Date(Date.UTC(1899, 11, 30) + Number(v) * 86400000).toISOString().slice(0, 10);
  }
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
    m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/); // MM/dd/yyyy (format Sheets kamu)
  if (m) return `${m[3]}-${m[1].padStart(2, '0')}-${m[2].padStart(2, '0')}`;
  return null;
}

// Periode: tanggal 2 sampai tanggal 1 bulan berikutnya
let awal = $now.startOf('day').set({ day: TGL_MULAI });
if ($now.day < TGL_MULAI) awal = awal.minus({ months: 1 });
if (info.mode === 'lalu') awal = awal.minus({ months: 1 });
const akhir = awal.plus({ months: 1 });
const hariAkhir = akhir.minus({ days: 1 });
const isoAwal = awal.toFormat('yyyy-MM-dd');
const isoAkhir = akhir.toFormat('yyyy-MM-dd');
const rentang = `${awal.day} ${PENDEK[awal.month - 1]} - ${hariAkhir.day} ${PENDEK[hariAkhir.month - 1]}`;

// Data
const saldoAwal = angka($('Baca Pengaturan').first().json.Nilai);
const batas = {};
for (const it of $('Baca Anggaran').all()) {
  if (it.json.Kategori) batas[it.json.Kategori] = angka(it.json['Batas Bulanan']);
}

const trx = $input.all().map(i => i.json)
  .filter(j => j.Status === 'Aktif')
  .map(j => ({ iso: keIso(j.Tanggal), jumlah: angka(j.Jumlah), kategori: j.Kategori, ket: j.Keterangan, tipe: j.Tipe }))
  .filter(t => t.iso && t.iso >= isoAwal && t.iso < isoAkhir && t.jumlah > 0);

const masuk = trx.filter(t => t.tipe === 'Pemasukan').reduce((a, t) => a + t.jumlah, 0);
const keluarList = trx.filter(t => t.tipe === 'Pengeluaran');
const keluar = keluarList.reduce((a, t) => a + t.jumlah, 0);
const selisih = masuk - keluar;
const saldoAkhir = saldoAwal + selisih;

const perKat = {};
for (const t of keluarList) perKat[t.kategori] = (perKat[t.kategori] || 0) + t.jumlah;

const barisKat = Object.entries(perKat)
  .sort((a, b) => b[1] - a[1])
  .map(([k, v]) => {
    const persen = keluar > 0 ? Math.round((v / keluar) * 100) : 0;
    const ang = batas[k] > 0 ? ` / anggaran ${rp(batas[k])}` : '';
    return `${k} ${rp(v)} (${persen}%)${ang}`;
  });

const terbesar = [...keluarList].sort((a, b) => b.jumlah - a.jumlah).slice(0, 3)
  .map(t => `${t.ket} ${rp(t.jumlah)}`);

const judul = `Laporan ${BULAN[awal.month - 1]} ${awal.year} (${rentang})` + (info.mode === 'berjalan' ? ' - sementara' : '');

let balasan;
if (trx.length === 0) {
  balasan = `${judul}\nBelum ada transaksi pada periode ini.`;
} else {
  balasan = [
    judul,
    `Pemasukan: ${rp(masuk)}`,
    `Pengeluaran: ${rp(keluar)}`,
    `Selisih: ${selisih >= 0 ? '+' : '-'}${rp(selisih)}`,
    '',
    'Per kategori:',
    ...(barisKat.length ? barisKat : ['-']),
    '',
    `Terbesar: ${terbesar.length ? terbesar.join(', ') : '-'}`,
    `Saldo akhir: ${saldoAkhir < 0 ? '-' : ''}${rp(saldoAkhir)}`
  ].join('\n');
}

return [{ json: { chat_id: info.chat_id, balasan } }];

return [{
  json: {
    chat_id: $('Siapkan Pesan').first().json.chat_id,
    balasan: 'Ollama tidak aktif atau terlalu lama merespons. Pesanmu belum tercatat, kirim ulang nanti.'
  }
}];

return [{
  json: {
    chat_id: $('Siapkan Pesan').first().json.chat_id,
    balasan: 'Transaksi ini sudah tercatat sebelumnya.'
  }
}];
